toolArgs.file_text:
/* Chat page layout */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel list sidebar */
.channel-list {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    padding: 1rem;
    overflow-y: auto;
    border-right: 1px solid #23272a;
}

.channel-list-header {
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    margin-bottom: 0.75rem;
}

.channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #40444b;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 0.5rem;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main message area */
.chat-main {
    width: 55%;
    display: flex;
    flex-direction: column;
    transition: width 0.2s ease;
}

.chat-main.expanded {
    width: 80%;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
    background: #fff;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

.message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #6b7280;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    color: #6b7280;
    padding: 0.5rem;
    font-size: 0.85rem;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #6b7280;
}

/* Message item */
.message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
}

.message-item:hover {
    background: #f3f4f6;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #9ca3af;
}

.message-content {
    margin-top: 0.25rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

.message-reactions {
    display: flex;
    gap: 0.25rem;
    margin-top: 0.35rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #e5e7eb;
    border: 1px solid #d1d5db;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

.reaction-badge:hover {
    background: #dbeafe;
    border-color: #93c5fd;
}

.thread-link {
    background: none;
    border: none;
    color: #2563eb;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message hover actions */
.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 0.25rem;
    display: flex;
    gap: 0.25rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.action-btn {
    background: none;
    border: none;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
}

.action-btn:hover {
    background: #f3f4f6;
}

.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 0.35rem;
    display: flex;
    gap: 0.25rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #f3f4f6;
}

/* Message input */
.message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #e3e5e8;
    background: #fff;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

.message-input textarea:focus {
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.15);
}

.send-button {
    background: #2563eb;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

.send-button:hover:not(:disabled) {
    background: #1d4ed8;
}

.send-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
.thread-panel {
    width: 25%;
    min-width: 250px;
    border-left: 1px solid #e3e5e8;
    display: flex;
    flex-direction: column;
    background: #fafbfc;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #6b7280;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
}

.close-btn:hover {
    background: #e5e7eb;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
    background: #f3f4f6;
}

.thread-root-message .message-author {
    font-weight: 700;
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #374151;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

